#include <cstddef>
#include <filesystem>
#include <string_view>

std::size_t countByExtension(const std::filesystem::path& folder, std::string_view extension)
{
    namespace fs = std::filesystem;
    if (!fs::is_directory(folder))
    {
        return 0;
    }
    std::size_t count{ 0 };
    for (const fs::directory_entry& entry : fs::directory_iterator{ folder })
    {
        if (entry.is_regular_file() && entry.path().extension() == extension)
        {
            ++count;
        }
    }
    return count;
}

