#include <fstream>
namespace fs = std::filesystem;
struct TempDir {
    fs::path path{ "xenon_dir_test" };
    TempDir() { fs::remove_all(path); fs::create_directories(path / "sub"); for (const char* name : { "a.txt", "b.txt", "c.md", "sub/d.txt" }) std::ofstream{ path / name } << "x"; fs::create_directories(path / "folder.txt"); }
    ~TempDir() { std::error_code ec; fs::remove_all(path, ec); }
};
TEST("counts matching files in the folder itself") { TempDir d; CHECK_EQ(countByExtension(d.path, ".txt"), 2u); CHECK_EQ(countByExtension(d.path, ".md"), 1u); CHECK_EQ(countByExtension(d.path, ".cpp"), 0u); }
TEST("a folder that does not exist") { CHECK_EQ(countByExtension("xenon_no_such_folder", ".txt"), 0u); }

